-- ----------------------------
-- 名远教育：教室与排课基础数据
-- 来源：暑秋各年级课表.xlsx / 总表
-- 生成时间：2026-08-01 23:17:13
-- 说明：本文件仅创建两张业务表并导入当前预览数据，请确认后再执行。
-- ----------------------------

set names utf8mb4;
set foreign_key_checks = 0;

-- ----------------------------
-- 1、教室信息表
-- ----------------------------
create table if not exists edu_classroom (
  classroom_id      bigint(20)      not null auto_increment    comment '教室ID',
  classroom_code    varchar(32)     not null                   comment '教室编码',
  campus_name       varchar(50)     not null                   comment '校区名称',
  classroom_name    varchar(50)     not null                   comment '教室名称',
  status            char(1)         default '0'                comment '状态（0正常 1停用）',
  create_by         varchar(64)     default ''                 comment '创建者',
  create_time       datetime                                   comment '创建时间',
  update_by         varchar(64)     default ''                 comment '更新者',
  update_time       datetime                                   comment '更新时间',
  remark            varchar(500)    default null               comment '备注',
  primary key (classroom_id),
  unique key uk_edu_classroom_code (classroom_code),
  key idx_edu_classroom_campus (campus_name),
  key idx_edu_classroom_status (status)
) engine=innodb auto_increment=100 comment = '教室信息表';

-- ----------------------------
-- 2、课程排课表
-- ----------------------------
create table if not exists edu_course_schedule (
  schedule_id        bigint(20)      not null auto_increment    comment '排课ID',
  schedule_code      varchar(32)     not null                   comment '排课编码',
  classroom_id       bigint(20)      default null               comment '教室ID（为空表示未定教室）',
  course_year        int(4)          default 2026               comment '课程年份',
  term_name          varchar(20)     not null                   comment '学期（暑假/秋季）',
  period_name        varchar(20)     not null                   comment '期次或上课日',
  time_slot          varchar(30)     not null                   comment '时段',
  start_time         time            default null               comment '开始时间',
  end_time           time            default null               comment '结束时间',
  grade_name         varchar(20)     not null                   comment '年级',
  subject_name       varchar(20)     not null                   comment '科目',
  teacher_name       varchar(30)     default ''                 comment '教师姓名',
  class_type         varchar(30)     default ''                 comment '班型',
  enrolled_count     int(4)          default null               comment '已报名人数',
  recruit_status     char(1)         default '0'                comment '招生状态（0可报名 1停招 2满班）',
  course_class_name  varchar(100)    not null                   comment '课程班名称',
  source_sheet       varchar(100)    default ''                 comment '来源Sheet',
  source_row         int(4)          default null               comment '来源行',
  source_col         varchar(10)     default ''                 comment '来源列',
  status             char(1)         default '0'                comment '状态（0正常 1停用）',
  del_flag           char(1)         default '0'                comment '删除标志（0代表存在 2代表删除）',
  create_by          varchar(64)     default ''                 comment '创建者',
  create_time        datetime                                   comment '创建时间',
  update_by          varchar(64)     default ''                 comment '更新者',
  update_time        datetime                                   comment '更新时间',
  remark             varchar(500)    default null               comment '备注',
  primary key (schedule_id),
  unique key uk_edu_schedule_code (schedule_code),
  key idx_edu_schedule_classroom (classroom_id),
  key idx_edu_schedule_query (term_name, period_name, grade_name, subject_name),
  key idx_edu_schedule_teacher (teacher_name),
  constraint fk_edu_schedule_classroom foreign key (classroom_id) references edu_classroom (classroom_id)
) engine=innodb auto_increment=1000 comment = '课程排课表';

-- ----------------------------
-- 初始化：教室信息
-- ----------------------------
ON DUPLICATE KEY UPDATE campus_name = values(campus_name), classroom_name = values(classroom_name), status = values(status), update_by = 'admin', update_time = sysdate(), remark = values(remark);

-- ----------------------------
-- 初始化：课程排课
-- ----------------------------
ON DUPLICATE KEY UPDATE classroom_id = values(classroom_id), term_name = values(term_name), period_name = values(period_name), time_slot = values(time_slot), start_time = values(start_time), end_time = values(end_time), grade_name = values(grade_name), subject_name = values(subject_name), teacher_name = values(teacher_name), class_type = values(class_type), enrolled_count = values(enrolled_count), recruit_status = values(recruit_status), course_class_name = values(course_class_name), source_sheet = values(source_sheet), source_row = values(source_row), source_col = values(source_col), update_by = 'admin', update_time = sysdate(), remark = values(remark);

set foreign_key_checks = 1;
